draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Confucius
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // Relationships
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 20, H/2);
  ctx.lineTo(W/2 + 100 - 20, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 20, H/2);
  ctx.lineTo(W/2, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 - 20, H/2);
  ctx.lineTo(W/2, H/2 + 30);
  ctx.stroke();

  // Social Harmony
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 100 + 50*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 100 + 50*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 100 + 50*Math.sin(t + Math.PI), 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 100 + 50*Math.sin(t + Math.PI), 10, 0, 2*Math.PI);
  ctx.stroke();

  ctx.restore();
}
